pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint256 unlockTime, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));

        // Ensure balances are reasonable
        vm.deal(sender, depositAmount + 1 ether);

        // First, deposit via Put
        vm.prank(sender);
        (bool putSuccess, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Put(uint256)", unlockTime));

        // Time travel to make unlockTime pass if needed
        vm.warp(block.timestamp + unlockTime + 1);

        // Now call Collect
        vm.prank(sender);
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // General rule: Collect succeeds only if contract has enough balance after Put
        // The reference C satisfies: if collectSuccess is true, then the balance of the contract after the call is >= the deposit (since no partial withdrawal beyond balance)
        // But we need a simpler invariant: The contract balance never becomes negative (impossible by EVM) AND Collect succeeds only when there was enough balance.
        // A simpler rule: After any Collect call (successful or not), the contract balance is at least 0 (always true) and if collectAmount <= c.Acc(sender).balance before Collect, then collectSuccess is true.
        // But we cannot read internal state. Use public getter: c.MinSum() is 1 ether.

        // Using the known MinSum = 1 ether, we can say: if collectAmount <= depositAmount && depositAmount >= 1 ether && block.timestamp > unlockTime then collectSuccess should be true (since balance was added).
        // However the reference may have the unlockTime check. So we use the public getter c.Acc(sender) which returns the struct.

        // Actually, we can read the sender's balance via public mapping
        (uint256 unlockFromAcc, uint256 balanceFromAcc) = c.Acc(sender);

        // The rule: Collect will succeed if and only if the balance from Acc is >= collectAmount and block.timestamp > unlockFromAcc and balanceFromAcc >= c.MinSum()
        // That is not atomic after the call because balance changes. But we can check after: collectSuccess implies balanceFromAcc after call is >= 0 and the deduction happened.

        // Simpler: The invariant that the contract balance is always >= sum of all user balances is not observable.
        // Use this: after Collect, the balance of the contract (address(c).balance) must be >= (total deposited - total collected). But we don't have those totals.

        // Another approach: For any inputs, the call to Collect either reverts or returns true, and if it returns true, the balance of the address(c) decreased by exactly collectAmount.
        // So we can record balance before and after.
        uint256 balBefore = address(c).balance;
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        uint256 balAfter = address(c).balance;

        // The rule: if success == true, then balBefore - balAfter == collectAmount
        assertTrue(!success || (balBefore - balAfter == collectAmount));
    }
}

