    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint unlockTime, uint deposit, uint withdraw) public {
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 100000);
        deposit = bound(deposit, 0.01 ether, 10 ether);
        withdraw = bound(withdraw, 0, deposit);

        // Deposit via fallback (Put with 0)
        vm.deal(address(this), deposit);
        (bool success, ) = address(c).call{value: deposit}("");
        assertTrue(success);

        // Set unlock time
        c.Put(unlockTime);

        // Warp past unlock time so Collect can succeed
        vm.warp(unlockTime + 1);

        // Collect
        c.Collect(withdraw);

        // The unlock time should still be > block.timestamp if the original Put set it to unlockTime
        // But we advanced time, so check the property: after Collect, unlock time > current block.timestamp
        // Actually the bug sets unlockTime = block.timestamp during Put, so after Collect it's <= block.timestamp
        // The reference always keeps unlockTime = max(original unlockTime, block.timestamp)
        // Since we warped to unlockTime+1, reference's unlockTime = unlockTime (which is > current time? No, current time is unlockTime+1, unlockTime < current time)
        // Wait, that would fail. Let me rethink.
        // Better: after Collect, the unlock time must be at least the original unlockTime.
        // The bug always sets it to block.timestamp of the Put call, so it loses the original value.
        // So we check: c.Acc(address(this)).unlockTime >= unlockTime (the one we passed to Put)
        (uint256 storedTime, uint256 storedBalance) = c.Acc(address(this));
        assertTrue(storedTime >= unlockTime);
    }
